function spliceCables(lengths) {
    const pieces = [...lengths];
    let labor = 0;
    while (pieces.length > 1) {
        pieces.sort((a, b) => a - b);
        const joined = pieces.shift() + pieces.shift();
        labor += joined;
        pieces.push(joined);
    }
    return labor;
}

function spliceCables(lengths) {
    const heap = [];
    const push = (value) => {
        heap.push(value);
        let i = heap.length - 1;
        while (i > 0) {
            const parent = (i - 1) >> 1;
            if (heap[parent] <= heap[i])
                break;
            [heap[parent], heap[i]] = [heap[i], heap[parent]];
            i = parent;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let i = 0;
            while (true) {
                const left = 2 * i + 1;
                const right = left + 1;
                let smallest = i;
                if (left < heap.length && heap[left] < heap[smallest])
                    smallest = left;
                if (right < heap.length && heap[right] < heap[smallest])
                    smallest = right;
                if (smallest === i)
                    break;
                [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
                i = smallest;
            }
        }
        return top;
    };
    for (const length of lengths)
        push(length);
    let labor = 0;
    while (heap.length > 1) {
        const joined = pop() + pop();
        labor += joined;
        push(joined);
    }
    return labor;
}
